// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ClearCart Очистить корзину
	// (DELETE /cart)
	ClearCart(ctx context.Context, request ClearCartRequestObject) (ClearCartResponseObject, error)
	// GetCart Получить текущую корзину пользователя
	// (GET /cart)
	GetCart(ctx context.Context, request GetCartRequestObject) (GetCartResponseObject, error)
	// AddCartItem Добавить блюдо в корзину
	// (POST /cart/items)
	AddCartItem(ctx context.Context, request AddCartItemRequestObject) (AddCartItemResponseObject, error)
	// RemoveCartItem Удалить блюдо из корзины
	// (DELETE /cart/items/{itemId})
	RemoveCartItem(ctx context.Context, request RemoveCartItemRequestObject) (RemoveCartItemResponseObject, error)
	// UpdateCartItem Изменить количество блюда в корзине
	// (PATCH /cart/items/{itemId})
	UpdateCartItem(ctx context.Context, request UpdateCartItemRequestObject) (UpdateCartItemResponseObject, error)
	// GetHealthz Проверка работоспособности сервиса
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// ListOrders Список заказов пользователя
	// (GET /orders)
	ListOrders(ctx context.Context, request ListOrdersRequestObject) (ListOrdersResponseObject, error)
	// Checkout Оформить заказ (checkout текущей корзины)
	// (POST /orders)
	Checkout(ctx context.Context, request CheckoutRequestObject) (CheckoutResponseObject, error)
	// GetOrder Получить заказ по id (мониторинг статуса)
	// (GET /orders/{orderId})
	GetOrder(ctx context.Context, request GetOrderRequestObject) (GetOrderResponseObject, error)
	// UpdateOrderStatus Смена статуса заказа сервисом заведения
	// (PATCH /orders/{orderId}/status)
	UpdateOrderStatus(ctx context.Context, request UpdateOrderStatusRequestObject) (UpdateOrderStatusResponseObject, error)
	// ListRestaurants Список заведений
	// (GET /restaurants)
	ListRestaurants(ctx context.Context, request ListRestaurantsRequestObject) (ListRestaurantsResponseObject, error)
	// GetRestaurant Получить заведение по id
	// (GET /restaurants/{restaurantId})
	GetRestaurant(ctx context.Context, request GetRestaurantRequestObject) (GetRestaurantResponseObject, error)
	// CreateCategory Добавить категорию меню
	// (POST /restaurants/{restaurantId}/categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// DeleteCategory Удалить категорию
	// (DELETE /restaurants/{restaurantId}/categories/{categoryId})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// CreateDish Добавить блюдо
	// (POST /restaurants/{restaurantId}/dishes)
	CreateDish(ctx context.Context, request CreateDishRequestObject) (CreateDishResponseObject, error)
	// DeleteDish Удалить блюдо (soft-delete)
	// (DELETE /restaurants/{restaurantId}/dishes/{dishId})
	DeleteDish(ctx context.Context, request DeleteDishRequestObject) (DeleteDishResponseObject, error)
	// UpdateDish Изменить название/описание/цену/категорию блюда
	// (PATCH /restaurants/{restaurantId}/dishes/{dishId})
	UpdateDish(ctx context.Context, request UpdateDishRequestObject) (UpdateDishResponseObject, error)
	// SetDishAvailability Изменить наличие блюда (в наличии / закончилось)
	// (PATCH /restaurants/{restaurantId}/dishes/{dishId}/availability)
	SetDishAvailability(ctx context.Context, request SetDishAvailabilityRequestObject) (SetDishAvailabilityResponseObject, error)
	// RestoreDish Восстановить ранее удалённое блюдо
	// (POST /restaurants/{restaurantId}/dishes/{dishId}/restore)
	RestoreDish(ctx context.Context, request RestoreDishRequestObject) (RestoreDishResponseObject, error)
	// GetRestaurantMenu Получить меню заведения (категории с блюдами)
	// (GET /restaurants/{restaurantId}/menu)
	GetRestaurantMenu(ctx context.Context, request GetRestaurantMenuRequestObject) (GetRestaurantMenuResponseObject, error)
	// ListRestaurantOrders Список заказов заведения
	// (GET /restaurants/{restaurantId}/orders)
	ListRestaurantOrders(ctx context.Context, request ListRestaurantOrdersRequestObject) (ListRestaurantOrdersResponseObject, error)
	// SetRestaurantStatus Открыть/закрыть заведение
	// (PATCH /restaurants/{restaurantId}/status)
	SetRestaurantStatus(ctx context.Context, request SetRestaurantStatusRequestObject) (SetRestaurantStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

